<?php if(!empty($preview['missing'])):?><div class="related-tools"><h3><?=count($preview['missing'])?> missing catalogue entries to create</h3><p>These entries will be published when their products import successfully. Nothing is created during preview. Entries used only by skipped or failed products are not created.</p></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Name</th><th>Slug</th><th>Parent category</th></tr></thead><tbody><?php foreach($preview['missing'] as $proposal):?><tr><td><?=e(App\Models\Modules::get($proposal['table'])['label'])?></td><td><?=e($proposal['data']['title'])?></td><td><?=e($proposal['data']['slug'])?></td><td><?=e($proposal['parent']?:'—')?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<div class="table-wrap"><table><thead><tr><th>CSV row</th><th>Product</th><th>Change</th><th>Status</th></tr></thead><tbody><?php foreach($preview['rows'] as $row):?><tr><td><?=$row['line']?></td><td><?=e($row['data']['title'])?></td><td><?=$row['id']?'Update existing #'.$row['id']:'Create new'?></td><td><?=e($row['data']['status'])?><?php if(!empty($row['data']['publish_at'])):?><small>Scheduled: <?=e(ist_datetime($row['data']['publish_at']))?></small><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php if(!$preview['errors']&&$preview['rows']):?><form method="post" class="related-tools"><?=csrf_field()?><input type="hidden" name="action" value="commit"><input type="hidden" name="import_token" value="<?=e($preview['token'])?>"><label class="check-label"><input type="checkbox" name="allow_updates" value="1"> Apply the reviewed updates to existing products. Unchecked updates are reported as skipped.</label><p>Confirming imports the reviewed products and creates their missing catalogue entries. Published products without a future schedule appear on the website.</p><button class="button">Confirm & import <?=count($preview['rows'])?> rows</button></form><?php endif?></section><?php endif?>
